/* Pioggia osservata AEMET, stazione B986 Formentera (8.5 km), ott-giu, 1941-2026 */
const PIOGGIA_2024 = 121.4;
const PIOGGIA_MEDIANA = 282.0;
const PIOGGIA_RANK = 1; /* piu' secco su 86 anni */
const PIOGGIA_N_ANNI = 86;

const PAROLE = {
  ndvi:[[0.30,'very lush'],[0.24,'lush'],[0.20,'fair'],[0.17,'average'],[0.14,'below average'],[0,'sparse']],
  ndmi:[[0.05,'well hydrated'],[0.00,'good'],[-0.05,'fair'],[-0.10,'somewhat dry'],[-0.15,'trending dry'],[-1,'dry']],
  ndre:[[0.20,'very charged'],[0.16,'good'],[0.13,'fair'],[0.10,'average'],[0.07,'below average'],[0,'depleted']],
  evi:[[0.21,'very lush'],[0.16,'lush'],[0.13,'fair'],[0.11,'average'],[0.09,'below average'],[0,'sparse']]
};
const NOMI={ndvi:'Vigor',ndmi:'Water status',ndre:'Chlorophyll',evi:'Biomass'};
const NOMI_LUNGHI={ndvi:'Canopy vigor',ndmi:'Water status',ndre:'Chlorophyll',evi:'Canopy biomass (EVI)'};

function calcolaRange(idx){
  let vals=[];
  for(const k in DATI){
    for(const a of ANNI){const y=DATI[k].y[a];if(y&&y[idx]!=null)vals.push(y[idx]);}
  }
  vals.sort((a,b)=>a-b);
  const p=(q)=>vals[Math.floor(q*(vals.length-1))];
  return {min:p(0.05),max:p(0.95)};
}
const RANGE={ndvi:calcolaRange('ndvi'),ndmi:calcolaRange('ndmi'),ndre:calcolaRange('ndre'),evi:calcolaRange('evi')};

function calcolaT(val,ix){
  if(val==null)return null;
  const r=RANGE[ix];
  let t=Math.max(0,Math.min(1,(val-r.min)/(r.max-r.min||1)));
  return Math.pow(t,1.3);
}
function colore(val,ix){
  const t=calcolaT(val,ix);
  if(t==null)return '#333';
  const stops=[[0,[105,40,32]],[.08,[139,58,42]],[.16,[170,90,58]],[.24,[195,135,82]],
    [.33,[214,182,112]],[.42,[200,190,116]],[.51,[165,185,105]],[.60,[125,172,92]],
    [.69,[90,155,82]],[.78,[65,150,140]],[.87,[55,130,175]],[.93,[48,108,190]],[1,[38,80,178]]];
  for(let i=0;i<stops.length-1;i++){const[t0,c0]=stops[i],[t1,c1]=stops[i+1];
    if(t>=t0&&t<=t1){const f=(t-t0)/(t1-t0);
      return`rgb(${Math.round(c0[0]+f*(c1[0]-c0[0]))},${Math.round(c0[1]+f*(c1[1]-c0[1]))},${Math.round(c0[2]+f*(c1[2]-c0[2]))})`;}}
  return'#888';
}
function chipColore(val,ix){
  const t=calcolaT(val,ix);
  if(t==null)return 'rgba(255,255,255,0.03)';
  const stops=[[0,[150,60,55]],[.5,[150,130,55]],[1,[75,120,60]]];
  for(let i=0;i<stops.length-1;i++){const[t0,c0]=stops[i],[t1,c1]=stops[i+1];
    if(t>=t0&&t<=t1){const f=(t-t0)/(t1-t0);
      const r=Math.round(c0[0]+f*(c1[0]-c0[0])),g=Math.round(c0[1]+f*(c1[1]-c0[1])),b=Math.round(c0[2]+f*(c1[2]-c0[2]));
      return`rgba(${r},${g},${b},0.28)`;}}
  return 'rgba(255,255,255,0.03)';
}function barColore(val,ix){
  const t=calcolaT(val,ix);
  if(t==null)return 'rgba(255,255,255,0.12)';
  const stops=[[0,[176,72,64]],[.5,[189,158,64]],[1,[92,148,74]]];
  for(let i=0;i<stops.length-1;i++){const[t0,c0]=stops[i],[t1,c1]=stops[i+1];
    if(t>=t0&&t<=t1){const f=(t-t0)/(t1-t0);
      const r=Math.round(c0[0]+f*(c1[0]-c0[0])),g=Math.round(c0[1]+f*(c1[1]-c0[1])),b=Math.round(c0[2]+f*(c1[2]-c0[2]));
      return `rgb(${r},${g},${b})`;}}
  return 'rgba(255,255,255,0.12)';
}

function valore(vid,ix,anno){const v=DATI[vid];if(!v)return null;const y=v.y[anno];return(y&&y[ix]!=null)?y[ix]:null;}
function parola(val,ix){if(val==null)return'···';for(const[s,t]of PAROLE[ix])if(val>=s)return t;return PAROLE[ix].slice(-1)[0][1];}

function stile(vid){
  const sel = vid===vidSel;
  const v=DATI[vid];
  const isCore = CORE8.includes(vid);
  if(!v){
    return {fillColor:'#333',fillOpacity:0.12,color:'#444',weight:0.5};
  }
  const val=valore(vid,idxSel,annoSel);
  let base;
  if(val==null)base={fillColor:'#333',fillOpacity:sel?0.45:0.2,color:sel?'#c9a84c':'#555',weight:sel?3:0.5};
  else base={fillColor:colore(val,idxSel),
    fillOpacity:vidSel&&!sel?0.35:(isCore?0.78:0.62),
    color:sel?'#f0d878':(isCore?'#1a1a1a':'rgba(255,255,255,0.75)'),
    weight:sel?3:(isCore?0.7:0.9)};
  return base;
}

const FORMENTERA_BOUNDS=L.latLngBounds([38.480,1.130],[38.870,1.840]);
function initMap(){
  map=L.map('map',{zoomControl:false,attributionControl:false,
    maxBounds:FORMENTERA_BOUNDS, maxBoundsViscosity:0.4, minZoom:10, maxZoom:19}).fitBounds([[38.658,1.535],[38.688,1.582]]);
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19}).addTo(map);
  L.control.zoom({position:'bottomright'}).addTo(map);
  L.geoJSON(VIGNE,{
    style:f=>stile(f.properties.vid),
    onEachFeature:(f,lyr)=>{const p=f.properties;layers[p.vid]=lyr;
      const has=!!DATI[p.vid];
      const tip=p.vid+(CORE8.includes(p.vid)?' (core)':(has?'':' (no data)'));
      lyr.bindTooltip(tip,{sticky:true,direction:'top'});
      if(has){
        lyr.on('click',()=>selVigna(p.vid));
        lyr.on('mouseover',()=>lyr.setStyle({weight:1.8,color:'#fff'}));
        lyr.on('mouseout',()=>lyr.setStyle(stile(p.vid)));
      }
    }
  }).addTo(map);
}
function ricolora(){for(const vid in layers)layers[vid].setStyle(stile(vid));ricoloraChips();}

function buildYearBar(){
  const bar=document.getElementById('year-bar');
  ANNI.forEach(y=>{const b=document.createElement('button');
    b.className='yr-btn'+(y===annoSel?' active':'');b.textContent=y;
    b.onclick=()=>{annoSel=y;document.querySelectorAll('.yr-btn').forEach(x=>x.classList.remove('active'));
      b.classList.add('active');ricolora();if(vidSel)aggDrawer();};
    bar.appendChild(b);});
}

function initTabs(){
  document.querySelectorAll('.tab-btn').forEach(b=>{b.onclick=()=>{idxSel=b.dataset.idx;
    document.querySelectorAll('.tab-btn').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');ricolora();if(vidSel)aggDrawer();};});
}

function centraSu(vid){
  const lyr=layers[vid]; if(!lyr)return;
  const isMobile=window.innerWidth<=768;
  const drawerW=isMobile?0:385;
  map.fitBounds(lyr.getBounds(),{
    paddingTopLeft:[60,60],
    paddingBottomRight:[drawerW+40,isMobile?120:60],
    maxZoom:18
  });
}
function selVigna(vid){
  vidSel=vid;
  document.getElementById('drawer').classList.add('open');
  ricolora();
  centraSu(vid);
  aggDrawer();
}

function serieMediaTutti(idx){
  const out={};
  for(const a of ANNI){
    const vals=[];
    for(const k in DATI){
      const y=DATI[k].y[a];
      if(y&&y[idx]!=null) vals.push(y[idx]);
    }
    if(vals.length) out[a]=vals.reduce((s,x)=>s+x,0)/vals.length;
  }
  return out;
}

function rankBadge(vid, anno){
  if(!CORE8.includes(vid)) return null;
  const r = RANK_CORE[anno] ? RANK_CORE[anno][vid] : null;
  if(r==null) return null;
  return r;
}

function cosaSappiamo(vid){
  const g=document.getElementById('cosa-sappiamo-grid');
  const isCore = CORE8.includes(vid);
  const v = DATI[vid];
  let rows = [];
  if(v && v.pendenza!=null){
    rows.push(["Slope (SIGPAC)", v.pendenza+"%"]);
  }
  if(isCore){
    const r = rankBadge(vid, annoSel);
    const rm = RANK_MEDIO[vid];
    rows.push(["Rank among the 8 core fields, "+annoSel, r ? (r+" of 8 (1 = most vigorous)") : "···"]);
    rows.push(["Average rank, 2017–2026", rm+" of 8 across all 10 years"]);
    if(vid==="C03"){
      rows.push(["What stands out", "C03 has been the single most vigorous of the 8 core fields in <b>every one of the 10 years</b> analysed — no exceptions. It also sits on one of the steepest slopes of the 8 core fields (33%, shared with C01 and C09), the opposite of what you'd expect if drainage alone explained vigor."]);
    } else if(vid==="C04"){
      rows.push(["What stands out", "C04 has ranked in the bottom three of the 8 core fields in all 10 years, and last in 6 of them. It is nearly flat (12% slope) — slope alone doesn't explain why it consistently underperforms."]);
    } else {
      rows.push(["Context", "Across the 8 core fields, C03 has been the strongest every single year since 2017, and C04 in the bottom three every year (last in 6 of 10) — a stable hierarchy, not a single bad season."]);
    }
  } else {
    rows.push(["Status", "Outside the 8 fields used for the main statistical analysis (below the 0.5 ha threshold, or excluded after visual check — see note)."]);
  }
  let html=rows.map(([l,val])=>`<div class="cs-row"><div class="cs-label">${l}</div><div class="cs-val">${val}</div></div>`).join('');
  g.innerHTML=html;
}

function aggDrawer(){
  const vid=vidSel,v=DATI[vid];
  if(!v){ return; }
  document.getElementById('drawer-title').textContent=vid;
  const isCore = CORE8.includes(vid);
  const slopeTxt = v.pendenza!=null ? ` · ${v.pendenza}% slope` : '';
  const sub=`${v.a} ha${slopeTxt}`+(isCore?' · core field':'');
  document.getElementById('drawer-subtitle').textContent=sub;
  const val=valore(vid,idxSel,annoSel);
  document.getElementById('read-label').textContent=NOMI_LUNGHI[idxSel]+' in '+annoSel;
  document.getElementById('br-value').textContent=val==null?'···':val.toFixed(3);
  document.getElementById('br-word').textContent=parola(val,idxSel);
  document.getElementById('and-label').textContent='Trend '+NOMI[idxSel]+' 2017–2026';
  const serie=ANNI.map(a=>({a,val:v.y[a]?v.y[a][idxSel]:null})).filter(x=>x.val!=null);
  const badge=document.getElementById('year-badges');
  if(badge&&serie.length){
    const best=serie.reduce((m,x)=>x.val>m.val?x:m);
    const worst=serie.reduce((m,x)=>x.val<m.val?x:m);
    badge.innerHTML=`<span class="ybadge up">best: ${best.a}</span>`+
                    `<span class="ybadge dn">worst: ${worst.a}</span>`;
  } else if(badge){ badge.innerHTML=''; }
  cosaSappiamo(vid);
  grafico(vid);
}
document.getElementById('drawer-close').onclick=()=>{document.getElementById('drawer').classList.remove('open');vidSel=null;ricolora();};

function grafico(vid){
  const v=DATI[vid],ctx=document.getElementById('chart');
  if(chart)chart.destroy();
  const serie=ANNI.map(a=>v.y[a]?v.y[a][idxSel]:null);
  const media=serieMediaTutti(idxSel);
  const mediaArr=ANNI.map(a=>media[a]!=null?media[a]:null);
  const iSel=ANNI.indexOf(annoSel);
  const valSel=valore(vid,idxSel,annoSel);
  const ptRadius=ANNI.map((a,i)=>i===iSel?6:3);
  const ptColor=ANNI.map((a,i)=>i===iSel?'#f0d878':'#c9a84c');
  const soglie=PAROLE[idxSel];
  let lo=-1,hi=1;
  if(valSel!=null)for(let i=0;i<soglie.length;i++){if(valSel>=soglie[i][0]){hi=(i>0?soglie[i-1][0]:1);lo=soglie[i][0];break;}}
  const bandPlugin={id:'band',beforeDatasetsDraw(c){
    if(valSel==null)return;const{ctx,chartArea:ca,scales}=c;const yT=scales.y.getPixelForValue(hi),yB=scales.y.getPixelForValue(lo);
    ctx.save();ctx.fillStyle='rgba(201,168,76,.10)';ctx.fillRect(ca.left,yT,ca.right-ca.left,yB-yT);
    const yV=scales.y.getPixelForValue(valSel);ctx.strokeStyle='rgba(240,216,120,.55)';ctx.setLineDash([3,3]);ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(ca.left,yV);ctx.lineTo(ca.right,yV);ctx.stroke();ctx.restore();}};
  chart=new Chart(ctx,{type:'line',
    data:{labels:ANNI,datasets:[
      {label:'this field',data:serie,borderColor:'#c9a84c',backgroundColor:'rgba(201,168,76,.1)',tension:.3,spanGaps:true,pointRadius:ptRadius,pointBackgroundColor:ptColor,pointBorderColor:ptColor},
      {label:'La Mola average',data:mediaArr,borderColor:'#8b2a2a',borderDash:[4,4],tension:.3,pointRadius:0,spanGaps:true}
    ]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{labels:{color:'#8a8478',font:{size:10}}},
        tooltip:{callbacks:{afterBody:(items)=>{const it=items[0];if(it&&it.datasetIndex===0&&it.parsed.y!=null)return parola(it.parsed.y,idxSel);}}}},
      scales:{x:{ticks:{color:'#8a8478',font:{size:9}},grid:{color:'rgba(255,255,255,.04)'}},
              y:{ticks:{color:'#8a8478',font:{size:9}},grid:{color:'rgba(255,255,255,.04)'}}}},
    plugins:[bandPlugin]});
}

/* RANKING PANEL: piccola tabella statica degli 8 campi core ordinati per rank medio */
function buildRankingPanel(){
  const el = document.getElementById('ranking-list');
  if(!el) return;
  const ordered = CORE8.slice().sort((a,b)=>RANK_MEDIO[a]-RANK_MEDIO[b]);
  el.innerHTML = ordered.map(c=>{
    const rm = RANK_MEDIO[c];
    const bar = Math.round((9-rm)/8*100);
    return `<div class="rk-row" data-vid="${c}"><span class="rk-name">${c}</span><div class="rk-bar-wrap"><div class="rk-bar" data-vid="${c}" style="width:${bar}%"></div></div><span class="rk-val">${rm}</span></div>`;
  }).join('');
  el.querySelectorAll('.rk-row').forEach(row=>{
    row.onclick=()=>selVigna(row.dataset.vid);
  });
  ricoloraChips();
}

/* Elenco compatto dei campi non-core (contesto, non nella statistica principale) */
function buildOtherFieldsPanel(){
  const el = document.getElementById('other-fields-list');
  if(!el) return;
  const others = Object.keys(DATI).filter(c=>!CORE8.includes(c)).sort((a,b)=>{
    const na=parseInt(a.slice(1),10), nb=parseInt(b.slice(1),10);
    return na-nb;
  });
  el.innerHTML = others.map(c=>`<span class="of-chip" data-vid="${c}">${c}</span>`).join('');
  el.querySelectorAll('.of-chip').forEach(chip=>{
    chip.onclick=()=>selVigna(chip.dataset.vid);
  });
  ricoloraChips();
}
function ricoloraChips(){
  document.querySelectorAll('.of-chip').forEach(chip=>{
    const vid=chip.dataset.vid;
    const val=valore(vid,idxSel,annoSel);
    chip.style.background=chipColore(val,idxSel);
  });
  document.querySelectorAll('.rk-bar').forEach(bar=>{
    const vid=bar.dataset.vid;
    const val=valore(vid,idxSel,annoSel);
    bar.style.background=barColore(val,idxSel);
  });
}

let annoSel='2026', idxSel='ndvi', vidSel=null, map, layers={}, chart=null;

function initHelp(){
  const btn=document.getElementById('help-btn');
  const overlay=document.getElementById('help-overlay');
  const close=document.getElementById('help-close');
  if(!btn||!overlay)return;
  btn.onclick=()=>overlay.classList.add('open');
  close.onclick=()=>overlay.classList.remove('open');
  overlay.onclick=(e)=>{if(e.target===overlay)overlay.classList.remove('open');};
}

initMap();buildYearBar();initTabs();buildRankingPanel();buildOtherFieldsPanel();initHelp();
